package com.bananalab.lite;
import java.io.*;import java.util.*;import org.json.*;
public class Stage38Check{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static SceneDraft go(CreatorSession c,Semilla m,String q,SceneDraft d)throws Exception{CreatorSession.Result r=c.apply(m,q,d);check(r.commit!=null,q+" => "+r.text);return r.commit;}
 public static void main(String[] args)throws Exception{String root=args[0];Semilla m=SemillaCheck.load(root+"/assets/language");CreatorSession c=new CreatorSession();SceneDraft d=go(c,m,"crea a Nube una criatura estrella azul con orejas largas y cola corta",null);check(d.get("criatura")!=null&&CustomCharacter.shape(d.get("criatura").look)==3&&CustomCharacter.ears(d.get("criatura").look)==2,"compositional design");String identity=d.get("criatura").designId;d=go(c,m,"cambia el cuerpo de Nube a gota",d);check(d.get("criatura").designId.equals(identity)&&CustomCharacter.shape(d.get("criatura").look)==4,"stable custom identity");check(c.apply(m,"crea una criatura con alas de dragon",d).commit==null,"unsupported parts not silently ignored");
 d=go(c,m,"agrega un pepino llamado Milo",d);CreatorSession.Result ask=c.apply(m,"quiero que baile",d);check(ask.commit==null&&!c.clarifyTemplate.isEmpty(),"clarify missing actor");c=CreatorSession.read(c.json());d=go(c,m,"Nube",d);check(d.actions.get(d.actions.size()-1).equals("baila")&&d.cast.get(d.actors.get(d.actors.size()-1)).label.equals("nube"),"clarification resumes prior request after reload");d=go(c,m,"me gustaria ver a Milo saltando",d);check(d.actions.get(d.actions.size()-1).equals("salta"),"natural paraphrase grounded");
 d=go(c,m,"Nube dice \"Hola, soy Nube.\"; Milo dice \"Vamos a jugar.\"",d);check(d.dialogue.size()==2&&d.sound,"actual spoken dialogue with audio enabled");SceneDraft copy=SceneDraft.read(d.json().toString());check(copy.dialogue.get(1).text.equals("Vamos a jugar."),"dialogue snapshot survives");d=go(c,m,"voz de Nube aguda",d);check(d.get("criatura").voice.equals("aguda"),"character voice");d=go(c,m,"hace que dure 30 segundos",d);check(Math.abs(SceneTiming.seconds(d)-30)<.01,"configurable duration");String saved=d.json().toString();check(c.apply(m,"hace que dure 121 segundos",d).commit==null&&saved.equals(d.json().toString()),"duration ceiling atomic");check(c.apply(m,"Nube dice hola 123",d).commit==null,"unsupported speech symbols explicit");
 short[] spoken=Soundtrack.pcm(d,SceneTiming.frames(d));check(spoken.length==30*Soundtrack.RATE,"audio/video duration alignment");int loud=0;for(short value:spoken)if(Math.abs((int)value)>5000)loud++;check(loud>100,"voice present beyond quiet ambience");float mouth=0;for(float t=0;t<VoiceSynth.duration("hola","media");t+=.01f)mouth=Math.max(mouth,VoiceSynth.mouth("hola","media",t));check(mouth>.9&&VoiceSynth.mouth("hola","media",-1)==0,"phoneme driven mouth envelope");
 SceneDraft longScene=d.copy();longScene.dialogue.clear();longScene.actions.clear();longScene.actors.clear();longScene.slots.clear();longScene.targets.clear();longScene.recipients.clear();longScene.fixedDuration=false;longScene.beatSeconds=1.5f;for(int i=0;i<20;i++)SceneDirector.step(longScene,longScene.cast.get(i%2),"saluda",i,"","");longScene=SceneDraft.read(longScene.json().toString());check(ObjectTransfer.beats(longScene)==20&&SceneTiming.seconds(longScene)>=30,"beyond old eight-slot limit");
 SceneDraft carry=go(c,m,"crea a Tony una banana detective; agrega un pepino llamado Bruno; Tony entrega una caja a Bruno",null);String owner=ObjectTransfer.at(carry,"caja",1,ObjectTransfer.beats(carry)).owner(),tony=carry.get("banana").designId;SceneDraft next=go(c,m,"prepara siguiente toma",carry);check(c.shots.size()==1&&next.actions.isEmpty()&&next.prop("caja").holder.equals(owner)&&next.get("banana").designId.equals(tony),"take continuation preserves final ownership and identity");CreatorSession reload=CreatorSession.read(c.json());check(reload.shots.size()==1,"take series persists");CreatorPersistenceCheck.Fake ctx=new CreatorPersistenceCheck.Fake();CreatorMemory.save(ctx,c,next);JSONObject series=BananaExporter.request(ctx,"series",null);check(series.getJSONArray("scenes").length()==2,"series contains archived and current takes");
 Scene jump=new Scene(carry);SceneDraft.Actor a=carry.get(owner);SceneDraft jumping=carry.copy();jumping.actions.clear();jumping.actors.clear();jumping.slots.clear();jumping.targets.clear();jumping.recipients.clear();jumping.prop("caja").holder=owner;SceneDirector.step(jumping,jumping.get(owner),"salta",0,"","");jump=new Scene(jumping);float[] p=jump.objectPoint("caja",.5f),hand=jump.hand(owner,.5f);check(Math.abs(p[1]-hand[1])<.001&&p[1]<jump.objectPoint("caja",0)[1]-5,"held object follows jump pose");float[] pose=jump.pose(owner,.3f,null),world=ActorGeometry.world(52,55,pose),local=ActorGeometry.local(world[0],world[1],pose[0],pose[1],pose[2],pose[3],pose[4]);check(Math.abs(local[0]-52)<.001&&Math.abs(local[1]-55)<.001,"shared forward/inverse grip transform");
 System.out.println("PASS contextual clarification, paraphrases, compositional bodies, dialogue, voice, lip envelope, long duration, shots and animated grip");
 }
}
